fields.InputDefinition:
{
  "goal": "Navigate to Data Explorer and open the 'Forum Categories' entity (or 'Products' if Forum Categories is unavailable). Click the New Record button, fill the Name field with 'Regression Delete Me', fill any required fields, and Save the new record. Then open that record and use the Delete action to delete it, confirming the deletion if prompted. Reach the state where the record has been removed (a delete confirmation appears, or the record no longer appears in the grid). Pages can take 10-30s to load in this resource-constrained environment, so wait for loads, saves, and deletes to finish rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 55,
  "judgeValidationCriteria": [
    "A record named 'Regression Delete Me' was created and saved successfully",
    "The Delete action was performed on that record and a delete confirmation or removed-from-grid state is visible",
    "No error messages, blank screens, or crash pages"
  ]
}
